    private void btnCalcularActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCalcularActionPerformed
        //Logica
        try{
            //leer datos
            double precio = Double.parseDouble(txtPrecio.getText());
            int cantidad = Integer.parseInt(txtCantidad.getText());
            //Validar
            if(precio <= 0 || cantidad <= 0){
                JOptionPane.showMessageDialog(rootPane, "Precio y Cantidad deben ser mayores a 0");
            }
            //Calcular Importe
            double total = precio * cantidad;
            //Aplica descuento?
            if(chkDescuento.isSelected() == true){
                total = total * 0.90;
            }
            txtTotal.setText("Total: S/ " + total);
            JOptionPane.showMessageDialog(rootPane, "Producto: " + cbxProducto.getSelectedItem() + " \nTotal: " + total);
            
            System.out.println(cbxProducto.getSelectedItem());
            
        }catch(NumberFormatException e){
            JOptionPane.showMessageDialog(rootPane, "Ingrese Valores Numéricos Válidos");
        }
    }//GEN-LAST:event_btnCalcularActionPerformed

